    // is the compact full name, the exact predicate is the About row "Market
    // wording", and `Rules.verified` carries the provider's own rules.
    private static let kokPredicate = "Will Femke Kok (NED) win the gold medal for Winter Olympics 2026: Speed Skating - Women's 500m at the 2026 Milano Cortina Winter Olympics?"
    private static let kokCondition = "0xbddee0620337135c0954d8536fcaeebbef430c796dcad072ca934cc710a5d000"
    private static let kokTokens = ["Yes": "8015203451758424254624644018470563478761525048434806320115142348030067468557",
                                    "No": "6871475823121509807575753550545899827766388996691185372123240045395047814247"]
    private static let kokProviderURL = "https://polymarket.com/event/winter-games-2026-speed-skating-womens-500m"
    /// The provider's rules: five paragraphs, 1,143 characters joined by blank lines.
    private static let kokRules = [
        "This market will resolve according to the participant (country team or individual participant as applicable to the event) that is awarded the gold medal at the 2026 Milano-Cortina Winter Olympics for Winter Olympics 2026: Speed Skating - Women's 500m event at the time of the corresponding medal/podium ceremony. Subsequent disqualifications or amendments will not be considered.",
        "If at any point it becomes impossible for a listed participant to win the 2026 Milano-Cortina Winter Olympics gold medal for Winter Olympics 2026: Speed Skating - Women's 500m event per the rules of IOC (e.g., participant is eliminated), the corresponding market will resolve to \"No\".",
