        "The resolution source will be official information from the International Olympic Committee (https://www.olympics.com/).",
    ]

    private func frame(_ o: O, _ phase: Phase) -> F { phase == .before ? o.before : o.final }

    private func identity(_ o: O) -> M.Identity { M.Identity(source: Self.source, market: o.market, side: o.side) }

    private func selection(_ o: O, scope: String = OlympicRecordedDetailsComposition10868Tests.scope) -> M.Selection {
        M.Selection(scope: scope, identity: identity(o))
    }

    private func mode(_ phase: Phase) -> M.Mode { phase == .before ? .pregame : .result }

    /// The legacy earlier reading: this original's own last trade before race day.
    private func legacyReading(_ o: O) -> M.Reading {
        o.before.end.map { M.Reading.value($0.figure, placement: $0.probability, provenance: $0.clock) }
            ?? .missing("No trade before race day")
    }

    /// The existing Details original. The final carries the reference's
    /// owner result words ("Happened" / "Didn’t happen").
    private func detailsOriginal(_ o: O, _ phase: Phase, mode: M.Mode? = nil, grade: M.Grade?? = nil,
                                 title: String? = nil, identity: M.Identity? = nil) -> M.Original {
        let packetGrade = frame(o, phase).grade.map { M.Grade(words: $0, provenance: nil) }
        return M.Original(identity: identity ?? self.identity(o), title: title ?? o.name,
                          outcome: Self.meaning[o.side]!, mode: mode ?? self.mode(phase), pregame: legacyReading(o),
                          later: nil, grade: grade ?? packetGrade,
                          about: M.About(source: "Polymarket", rules: .verified([Self.rule]),
                                         provenance: [M.Row(label: "Provider market", value: "Polymarket · market \(o.marketID)")],
                                         historicalQuote: nil),
                          beforeLabel: "Before race day")
    }

    private func catalogue(_ phase: Phase, _ originals: [M.Original]? = nil) -> M.Catalogue {
        M.Catalogue(scope: Self.scope, originals: originals ?? Self.originals.map { detailsOriginal($0, phase) })
    }

    private func marker(_ t: T) -> M.Marker { t.style == .hollow ? .hollow : .solid }

    private func value(_ t: T) -> M.Reading { .value(t.figure, placement: nil, provenance: t.clock) }

    /// The owner's election, read from the reference export: one reading for a
    /// single trade, two otherwise, and explicit missing words when empty.
    private func readings(_ f: F) -> [M.RecordedReading] {
        guard let end = f.end, let start = f.start else {
            return [M.RecordedReading(label: Self.emptyLabel, marker: .hollow, reading: .missing(Self.emptyWords))]
        }
        if f.single { return [M.RecordedReading(label: f.endLabel, marker: marker(end), reading: value(end))] }
        return [M.RecordedReading(label: f.startLabel, marker: marker(start), reading: value(start)),
                M.RecordedReading(label: f.endLabel, marker: marker(end), reading: value(end))]
    }

    private func trades(_ o: O, _ phase: Phase) -> [T] {
        if let sample = Self.samples.first(where: { $0.seriesID == o.seriesID }) {
            return phase == .before ? Array(sample.trades.prefix(sample.before)) : sample.trades
        }
        let f = frame(o, phase)
        return [f.start, f.end].compactMap { $0 }.reduce(into: [T]()) { all, t in
            if !all.contains(where: { $0.id == t.id }) { all.append(t) }
        }
    }

    private func point(_ t: T) -> FieldHistoryPoint10868 {
        FieldHistoryPoint10868(id: t.id, x: t.x, probability: t.probability, style: t.style)
    }

    private func series(_ o: O, _ phase: Phase, id: String? = nil) -> FieldHistorySeries10868 {
        FieldHistorySeries10868(
            id: id ?? o.seriesID, name: "\(o.name) · original \(o.side)", shape: .circle, tint: .blue,
            runs: trades(o, phase).map { FieldHistoryRun10868(id: "constructed-run:\($0.id)", points: [point($0)]) },
            links: [], labelPointID: nil, before: .absent(words: "Unavailable"), recorded: .absent(words: "Unavailable"),
            absentWords: nil, choose: nil)
    }

    /// The ready mini composition: plot first, key hidden, no chart control.
    private func history(_ o: O, _ phase: Phase, series: [FieldHistorySeries10868]? = nil,
                         selection: FieldHistoryOriginalSelection10868? = nil) -> FieldHistoryInput10868 {
        let f = frame(o, phase)
        let upper = phase == .before ? Self.raceDay : Self.reportAt
        var input = FieldHistoryInput10868(
            title: f.isEmpty ? "Recorded chance" : "Recorded chance · 0–\(f.top)",
            caption: nil,
            series: series ?? [self.series(o, phase)],
            selection: selection ?? .series(id: o.seriesID, missingWords: "This original isn’t in this history"),
            domain: FieldHistoryDomain10868(lower: Self.domainLower, upper: upper),
            ceiling: f.ceiling,
            yTicks: [FieldHistoryTick10868(value: 0, lines: ["0%"]), FieldHistoryTick10868(value: f.ceiling, lines: [f.top])],
            xTicks: [FieldHistoryTick10868(value: Self.domainLower, lines: ["Feb 6"]),
                     FieldHistoryTick10868(value: upper, lines: [phase == .before ? "Feb 14" : "Feb 15"])],
            guides: [], breaks: [],
            readout: .singleBefore(label: "Before race day"),
            markKey: FieldHistoryMarkKey10868(hollow: "Hollow: before race day", filled: "Filled: later recorded"),
            comparisonExplanation: nil, notes: [],
            summary: "\(o.name), \(Self.meaning[o.side]!). Dots are original \(o.side) trades.",
            plotHeight: 132, unboundReadingWords: "Unavailable", plotUnavailableWords: "Original history unavailable",
            windows: nil, scale: nil, moreOriginals: nil, details: nil, expand: nil, inspect: nil,
            previous: nil, next: nil, inspection: nil, layout: .expanded)
        input.showsKey = false
        input.plotAbsence = f.isEmpty
            ? FieldHistoryPlotAbsence10868(title: "No retained trades",
                                           words: "This original \(o.side) outcome has no captured probability history.")
            : nil
        return input
    }

    private func finish(_ f: F) -> M.ReportedFinish {
        f.finish.map { .reported(words: $0, spoken: nil) } ?? .unlinked(words: Self.notLinked)
    }

    private func context(_ o: O, _ phase: Phase, selection: M.Selection? = nil, mode: M.Mode? = nil,
                         seriesID: String? = nil, availability: String = OlympicRecordedDetailsComposition10868Tests.availability,
                         readings: [M.RecordedReading]? = nil, movement: String?? = nil,
                         history: FieldHistoryInput10868? = nil, finishLabel: String = "Reported finish",
                         finish: M.ReportedFinish?? = nil,
                         preview: FieldHistoryAction10868? = OlympicRecordedDetailsComposition10868Tests.preview,
                         expand: FieldHistoryAction10868? = OlympicRecordedDetailsComposition10868Tests.expand,
                         explore: FieldHistoryAction10868? = OlympicRecordedDetailsComposition10868Tests.explore,
                         unmatched: String = OlympicRecordedDetailsComposition10868Tests.unmatched) -> M.RecordedHistory {
        let f = frame(o, phase)
        return M.RecordedHistory(
            selection: selection ?? self.selection(o), mode: mode ?? self.mode(phase), seriesID: seriesID ?? o.seriesID,
            availability: availability, readings: readings ?? self.readings(f),
            movement: movement ?? (f.isEmpty ? nil : f.movement), history: history ?? self.history(o, phase),
            finishLabel: finishLabel, finish: finish ?? (phase == .final ? self.finish(f) : nil),
            preview: preview, expand: expand, explore: explore, unmatchedWords: unmatched)
    }

    private func resolve(_ o: O, _ phase: Phase, _ context: M.RecordedHistory?, hasCallback: Bool = true,
                         catalogue: M.Catalogue? = nil, selection: M.Selection?? = nil) -> M.RecordedPresentation? {
        M.recorded(catalogue: catalogue ?? self.catalogue(phase), selection: selection ?? self.selection(o),
                   context: context, hasCallback: hasCallback)
    }

    private func recordedShown(_ presentation: M.RecordedPresentation?) -> M.RecordedShown? {
        if case .recorded(let shown)? = presentation { return shown }
        return nil
    }

    private func legacy(_ o: O, _ phase: Phase) -> M.Content {
        M.content(catalogue: catalogue(phase), selection: selection(o))!
    }

    // MARK: - Every original, both phases

    func testEveryOriginalInBothPhasesShowsItsOwnRecordedEndpointsLabelsResultAndFinish() throws {
        XCTAssertEqual(Self.originals.count, 72)
        var empty: [Phase: Int] = [:]
        var linked = 0
        var single = 0
        var grades: [String: Int] = [:]
        for o in Self.originals {
            for phase in Phase.allCases {
                let f = frame(o, phase)
                let ctx = context(o, phase)
                let shown = try XCTUnwrap(recordedShown(resolve(o, phase, ctx)), "\(o.name) \(o.side) \(phase)")
                let id = "\(o.name) \(o.side) \(phase)"
                XCTAssertEqual(shown.selection, selection(o), id)
                XCTAssertEqual(shown.content.title, o.name, id)
                XCTAssertEqual(shown.content.outcome, Self.meaning[o.side], id)
                XCTAssertEqual(shown.availability, Self.availability, id)
                XCTAssertEqual(shown.history, ctx.history, "the owner's input, unchanged: \(id)")
                XCTAssertEqual(shown.content.about, legacy(o, phase).about, id)
                XCTAssertEqual(shown.content.rules, .verified([Self.rule]), id)
                guard case .original(let series, _) = G.selectedSummary(shown.history) else {
                    return XCTFail("single-original frame: \(id)")
                }
                XCTAssertEqual(series.id, o.seriesID, id)

                if let start = f.start, let end = f.end {
                    let expected: [(String, T)] = f.single ? [(f.endLabel, end)] : [(f.startLabel, start), (f.endLabel, end)]
                    XCTAssertEqual(shown.content.readings.map(\.label), expected.map { $0.0 }, id)
                    XCTAssertEqual(shown.content.readings.map(\.text), expected.map { $0.1.figure }, id)
                    XCTAssertEqual(shown.content.readings.map(\.provenance), expected.map { Optional($0.1.clock) }, id)
                    XCTAssertEqual(shown.content.readings.map(\.marker), expected.map { marker($0.1) }, id)
                    XCTAssertTrue(shown.content.readings.allSatisfy(\.isValue), id)
                    XCTAssertTrue(shown.showsPlot, id)
                    XCTAssertEqual(shown.movement, f.movement, id)
                    XCTAssertEqual(shown.preview, Self.preview, id)
                    XCTAssertEqual(shown.expand, Self.expand, id)
                    XCTAssertEqual(G.marks(series, in: shown.history).map(\.id), trades(o, phase).map(\.id), id)
                    if f.single { single += 1 }
                } else {
                    empty[phase, default: 0] += 1
                    XCTAssertEqual(shown.content.readings.map(\.text), [Self.emptyWords], id)
                    XCTAssertFalse(shown.showsPlot, id)
                    XCTAssertNil(shown.preview, id)
                    XCTAssertNil(shown.expand, id)
                }
                XCTAssertEqual(shown.explore, Self.explore, id)

                switch phase {
                case .before:
                    XCTAssertNil(shown.content.result, id)
                    XCTAssertNil(shown.finish, id)
                case .final:
                    let grade = try XCTUnwrap(f.grade, id)
                    grades[grade, default: 0] += 1
                    XCTAssertEqual(shown.content.result, M.ShownResult(words: grade, provenance: M.resultTimeUnknown), id)
                    let shownFinish = try XCTUnwrap(shown.finish, id)
                    XCTAssertEqual(shownFinish.label, "Reported finish", id)
                    XCTAssertEqual(shownFinish.words, f.finish ?? Self.notLinked, id)
                    XCTAssertEqual(shownFinish.isLinked, f.finish != nil, id)
                    if f.finish != nil { linked += 1 }
                }
            }
        }
        XCTAssertEqual(empty[.before], 32)
        XCTAssertEqual(empty[.final], 32)
        XCTAssertEqual(linked, 34)
        XCTAssertEqual(single, 2, "two real single-trade finals")
        XCTAssertEqual(grades, ["Happened": 36, "Didn’t happen": 36])
    }

    func testKokNoReadsItsOwnIndependentTradesNeverTheYesComplement() throws {
        let yes = try XCTUnwrap(recordedShown(resolve(Self.kok, .before, context(Self.kok, .before))))
        let no = try XCTUnwrap(recordedShown(resolve(Self.kokNo, .before, context(Self.kokNo, .before))))
        XCTAssertEqual(yes.content.readings.map(\.text), ["68%", "78%"])
        XCTAssertEqual(no.content.readings.map(\.text), ["29%", "23%"])
        XCTAssertEqual(yes.content.readings.map(\.label), ["First captured trade", "Before race day"])
        XCTAssertEqual(yes.movement, "10 points higher")
        XCTAssertEqual(no.movement, "6 points lower")
        let yesFinal = try XCTUnwrap(recordedShown(resolve(Self.kok, .final, context(Self.kok, .final))))
        let noFinal = try XCTUnwrap(recordedShown(resolve(Self.kokNo, .final, context(Self.kokNo, .final))))
        XCTAssertEqual(yesFinal.content.readings.map(\.text), ["78%", "99.9%"])
        XCTAssertEqual(noFinal.content.readings.map(\.text), ["23%", "0.1%"])
        XCTAssertEqual(yesFinal.content.readings.map(\.marker), [.hollow, .solid], "before race day hollow · later filled")
        XCTAssertEqual(yesFinal.content.readings.map(\.label), ["Before race day", "Last recorded trade"])

        let yesTrades = Set(Phase.allCases.flatMap { trades(Self.kok, $0).map(\.id) })
        let noTrades = Set(Phase.allCases.flatMap { trades(Self.kokNo, $0).map(\.id) })
        XCTAssertTrue(yesTrades.isDisjoint(with: noTrades), "independent original trades")
        XCTAssertNotEqual(Self.kok.seriesID, Self.kokNo.seriesID)
        // Each endpoint is that side's own trade at its own time — even where the
        // two final figures happen to total 100%, neither is derived from the other.
        for phase in Phase.allCases {
            let y = frame(Self.kok, phase), n = frame(Self.kokNo, phase)
            XCTAssertNotEqual(y.start?.x, n.start?.x)
            XCTAssertNotEqual(y.end?.x, n.end?.x)
        }
        // Mapping Kok No's context onto Kok Yes's selection borrows none of it.
        XCTAssertEqual(resolve(Self.kok, .final, context(Self.kokNo, .final)),
                       .unmatched(legacy(Self.kok, .final), words: Self.unmatched))
    }

    func testTheTwoRealSameEndpointFinalsShowOneReadingAndNoInventedMovement() throws {
        for name in ["Kristina Silaeva", "Rio Yamada"] {
            let o = Self.original(name, "No")
            let f = o.final
            XCTAssertTrue(f.single, name)
            XCTAssertEqual(f.start?.id, f.end?.id, "the same retained trade: \(name)")
            let shown = try XCTUnwrap(recordedShown(resolve(o, .final, context(o, .final))), name)
            XCTAssertEqual(shown.content.readings.count, 1, name)
            XCTAssertEqual(shown.content.readings.first?.label, "Before race day · last recorded", name)
            XCTAssertEqual(shown.content.readings.first?.text, f.end?.figure, name)
            XCTAssertEqual(shown.content.readings.first?.marker, .hollow, name)
            XCTAssertEqual(shown.movement, "No later recorded trade", name)
            XCTAssertTrue(shown.showsPlot, name)
        }
        // Equal values at two different trades are still two readings.
        let inegawa = Self.original("Kurumi Inegawa", "No")
        XCTAssertFalse(inegawa.final.single)
        XCTAssertNotEqual(inegawa.final.start?.id, inegawa.final.end?.id)
        let equal = try XCTUnwrap(recordedShown(resolve(inegawa, .final, context(inegawa, .final))))
        XCTAssertEqual(equal.content.readings.map(\.text), ["99.9%", "99.9%"])
        XCTAssertEqual(equal.content.readings.map(\.label), ["Before race day", "Last recorded trade"])
        XCTAssertEqual(equal.movement, "Same recorded chance at both times")
    }

    func testThirtyTwoEmptyOriginalsShowCompactAbsenceWordsAndNeverAZero() throws {
        let empties = Self.originals.filter { $0.final.isEmpty }
        XCTAssertEqual(empties.count, 32)
        XCTAssertEqual(Self.originals.filter { $0.before.isEmpty }.map(\.seriesID), empties.map(\.seriesID))
        for o in empties {
            for phase in Phase.allCases {
                // A movement the owner populated anyway stays hidden without a plot.
                let shown = try XCTUnwrap(recordedShown(resolve(o, phase, context(o, phase, movement: "Comparison unavailable"))))
                let absence = try XCTUnwrap(G.plotAbsence(shown.history), o.name)
                XCTAssertEqual(absence.title, "No retained trades")
                XCTAssertEqual(G.absenceWords(absence), "This original \(o.side) outcome has no captured probability history.")
                XCTAssertFalse(G.showsPlot(shown.history))
                XCTAssertTrue(shown.history.series.allSatisfy { $0.runs.isEmpty })
                XCTAssertNil(shown.movement)
                XCTAssertNil(shown.preview, "no preview of nothing")
                XCTAssertNil(shown.expand, "no expand of nothing")
                XCTAssertEqual(shown.explore, Self.explore, "the full reader still opens")
                let reading = try XCTUnwrap(shown.content.readings.first)
                XCTAssertEqual(reading.label, "Before race day")
                XCTAssertEqual(reading.text, "Unavailable")
                XCTAssertFalse(reading.isValue)
                XCTAssertNil(reading.provenance)
                XCTAssertNil(reading.placement)
                for text in shown.content.readings.map(\.text) + [M.spoken(shown)] {
                    XCTAssertFalse(text.contains("0%"), "missing is never zero: \(o.name)")
                    XCTAssertFalse(text.contains("100%"), "missing is never certain: \(o.name)")
                }
            }
        }
    }

    // MARK: - Identity and suppression

    func testMalformedDuplicateWithdrawnAndOutOfScopeSelectionsResolveNoDetails() {
        let o = Self.kok
        let ctx = context(o, .final)
        XCTAssertNil(resolve(o, .final, ctx, selection: .some(nil)))
        XCTAssertNil(resolve(o, .final, ctx, selection: selection(o, scope: "fixture:another-event")))
        XCTAssertNil(resolve(o, .final, ctx, selection: selection(o, scope: "  ")))
        let withdrawn = M.Selection(scope: Self.scope, identity: M.Identity(source: Self.source,
                                                                            market: "fixture-original:withdrawn", side: "Yes"))
        XCTAssertNil(resolve(o, .final, ctx, selection: withdrawn))
        let blankSide = M.Selection(scope: Self.scope, identity: M.Identity(source: Self.source, market: o.market, side: " "))
        XCTAssertNil(resolve(o, .final, ctx, selection: blankSide))
        var duplicated = Self.originals.map { detailsOriginal($0, .final) }
        duplicated.append(detailsOriginal(o, .final))
        XCTAssertNil(resolve(o, .final, ctx, catalogue: catalogue(.final, duplicated)), "a duplicate is no original")
        let blankTitle = Self.originals.map { $0.seriesID == o.seriesID ? detailsOriginal($0, .final, title: " ") : detailsOriginal($0, .final) }
        XCTAssertNil(resolve(o, .final, ctx, catalogue: catalogue(.final, blankTitle)))
        XCTAssertNil(M.recorded(catalogue: nil, selection: selection(o), context: ctx, hasCallback: true))
    }

    func testAContextForAnotherScopeSideModeSeriesOrCompositionBorrowsNothing() {
        let o = Self.kok
        let expected = M.RecordedPresentation.unmatched(legacy(o, .final), words: Self.unmatched)
        var stray = history(o, .final)
        stray.layout = .focused
        var keyed = history(o, .final)
        keyed.showsKey = true
        let base = history(o, .final)
        var scaled = FieldHistoryInput10868(
            title: base.title, caption: base.caption, series: base.series, selection: base.selection, domain: base.domain,
            ceiling: base.ceiling, yTicks: base.yTicks, xTicks: base.xTicks, guides: [], breaks: [], readout: base.readout,
            markKey: base.markKey, comparisonExplanation: nil, notes: [], summary: base.summary,
            plotHeight: base.plotHeight, unboundReadingWords: base.unboundReadingWords,
            plotUnavailableWords: base.plotUnavailableWords, windows: nil,
            scale: FieldHistoryAction10868(id: "constructed-scale", label: "0–100%", spokenLabel: nil, isAvailable: true),
            moreOriginals: nil, details: nil, expand: nil, inspect: nil, previous: nil, next: nil, inspection: nil,
            layout: .expanded)
        scaled.showsKey = false
        let three = readings(o.final) + [M.RecordedReading(label: "Constructed third", marker: .solid,
                                                           reading: .value("50%", placement: nil, provenance: "constructed"))]
        let twins = readings(o.final).map { M.RecordedReading(label: "Before race day", marker: $0.marker, reading: $0.reading) }
        let mismatched: [(String, M.RecordedHistory)] = [
            ("other side", context(Self.kokNo, .final)),
            ("other scope", context(o, .final, selection: selection(o, scope: "fixture:another-event"))),
            ("expected mode", context(o, .final, mode: .pregame)),
            ("comparison mode", context(o, .final, mode: .comparison(.recorded))),
            ("other series id", context(o, .final, seriesID: Self.kokNo.seriesID)),
            ("blank series id", context(o, .final, seriesID: " ")),
            ("history selects another series",
             context(o, .final, history: history(o, .final, selection: .series(id: Self.kokNo.seriesID, missingWords: "x")))),
            ("two originals in the frame",
             context(o, .final, history: history(o, .final, series: [series(o, .final), series(Self.kokNo, .final)]))),
            ("withdrawn history selection", context(o, .final, history: history(o, .final, selection: .unavailable(words: "Withdrawn")))),
            ("not expanded", context(o, .final, history: stray)),
            ("field key shown", context(o, .final, history: keyed)),
            ("chart control", context(o, .final, history: scaled)),
            ("three readings", context(o, .final, readings: three)),
            ("no reading", context(o, .final, readings: [])),
            ("duplicate labels", context(o, .final, readings: twins)),
            ("blank availability", context(o, .final, availability: "  ")),
        ]
        for (name, ctx) in mismatched {
            XCTAssertEqual(resolve(o, .final, ctx), expected, name)
        }
        XCTAssertEqual(resolve(o, .final, context(o, .final, seriesID: " ", unmatched: " ")),
                       .unmatched(legacy(o, .final), words: M.recordedUnavailable))
        // The before frame of the same original is the other phase's context.
        XCTAssertEqual(resolve(o, .final, context(o, .before)),
                       .unmatched(legacy(o, .final), words: Self.unmatched))
    }

    func testBeforeHidesDeliberatelyPopulatedGradeAndFinish() throws {
        let o = Self.kokNo
        let populated = Self.originals.map {
            detailsOriginal($0, .before, grade: .some(M.Grade(words: "Didn’t happen", provenance: "constructed future grade")))
        }
        let ctx = context(o, .before, finish: .some(.reported(words: "Gold · 36.49s", spoken: nil)))
