        }
        let compared = try XCTUnwrap(recordedShown(resolve(o, .final, context(o, .final, mode: .comparison(.recorded)),
                                                   catalogue: catalogue(.final, comparing))))
        XCTAssertNil(compared.content.result)
        XCTAssertNil(compared.finish)
    }

    func testTheContractResultAndTheReportedFinishStaySeparate() throws {
        let kokNo = try XCTUnwrap(recordedShown(resolve(Self.kokNo, .final, context(Self.kokNo, .final))))
        XCTAssertEqual(kokNo.content.result?.words, "Didn’t happen")
        XCTAssertEqual(kokNo.finish, M.ShownFinish(label: "Reported finish", words: "Gold · 36.49s", isLinked: true,
                                                   spoken: "Reported finish: Gold · 36.49s"))
        XCTAssertEqual(M.resultSpoken(kokNo),
                       "Original market result: Didn’t happen, Settlement time unknown. Reported finish: Gold · 36.49s.")
        let silaeva = try XCTUnwrap(recordedShown(resolve(Self.original("Kristina Silaeva", "No"), .final,
                                                  context(Self.original("Kristina Silaeva", "No"), .final))))
        XCTAssertEqual(silaeva.content.result?.words, "Happened")
        XCTAssertEqual(silaeva.finish?.words, "#18 · 38.33s")

        for o in [Self.kokNo, Self.original("Kristina Silaeva", "No")] {
            let ctx = context(o, .final)
            let series = try XCTUnwrap(ctx.history.series.first)
            XCTAssertNil(series.keyContext, "the finish is never a key context here")
            XCTAssertEqual(G.marks(series, in: ctx.history).map(\.id), trades(o, .final).map(\.id),
                           "no finish point or endpoint is added")
            XCTAssertTrue(G.marks(series, in: ctx.history).allSatisfy { $0.x <= Self.reportAt })
        }

        let unlinkedOriginal = Self.original("Kurumi Inegawa", "No")
        let unlinked = try XCTUnwrap(recordedShown(resolve(unlinkedOriginal, .final, context(unlinkedOriginal, .final))))
        XCTAssertEqual(unlinked.finish, M.ShownFinish(label: "Reported finish", words: "Not linked", isLinked: false,
                                                      spoken: "Reported finish: Not linked"))
        let absent = try XCTUnwrap(recordedShown(resolve(Self.kok, .final, context(Self.kok, .final, finish: .some(nil)))))
        XCTAssertEqual(absent.finish?.words, M.reportedFinishUnavailable)
        XCTAssertEqual(absent.finish?.isLinked, false)
        let blank = try XCTUnwrap(recordedShown(resolve(Self.kok, .final,
                                                context(Self.kok, .final, finishLabel: " ",
                                                        finish: .some(.reported(words: " ", spoken: "constructed"))))))
        XCTAssertEqual(blank.finish, M.ShownFinish(label: M.reportedFinishLabel, words: M.reportedFinishUnavailable,
                                                   isLinked: false, spoken: "Reported finish: Reported finish unavailable"))
        let spoken = try XCTUnwrap(recordedShown(resolve(Self.kok, .final,
                                                 context(Self.kok, .final,
                                                         finish: .some(.reported(words: "Gold · 36.49s",
                                                                                 spoken: "Reported finish: gold in 36.49 seconds"))))))
        XCTAssertEqual(spoken.finish?.spoken, "Reported finish: gold in 36.49 seconds")
        XCTAssertFalse(M.spoken(kokNo).contains("Gold"), "the finish is not part of the probability summary")
    }

    // MARK: - Owner words

    func testRealZeroMissingUnknownAndVoidStayTheOwnersOwnWords() throws {
        let o = Self.kok
        // CONSTRUCTED readings.
        let constructed = [
            M.RecordedReading(label: "Constructed zero", marker: .hollow, reading: .value("0%", placement: 0, provenance: " ")),
            M.RecordedReading(label: "Constructed missing", marker: .solid, reading: .missing("No retained baseline trade")),
        ]
        let shown = try XCTUnwrap(recordedShown(resolve(o, .before, context(o, .before, readings: constructed))))
        XCTAssertEqual(shown.content.readings.map(\.text), ["0%", "No retained baseline trade"])
        XCTAssertEqual(shown.content.readings.map(\.isValue), [true, false])
        XCTAssertEqual(shown.content.readings.map(\.provenance), [M.timeUnknown, nil])
        let blank = [M.RecordedReading(label: "Constructed blank", marker: .solid, reading: .value(" ", placement: nil, provenance: "x"))]
        let blankShown = try XCTUnwrap(recordedShown(resolve(o, .before, context(o, .before, readings: blank))))
        XCTAssertEqual(blankShown.content.readings.map(\.text), [M.unavailable])
        XCTAssertEqual(blankShown.content.readings.map(\.isValue), [false])

        // CONSTRUCTED grades through the existing result path.
        let cases: [(M.Grade?, M.ShownResult)] = [
            (M.Grade(words: "Void", provenance: nil), M.ShownResult(words: "Void", provenance: M.resultTimeUnknown)),
            (M.Grade(words: "Not yet confirmed", provenance: "Constructed settlement note"),
             M.ShownResult(words: "Not yet confirmed", provenance: "Constructed settlement note")),
            (M.Grade(words: " ", provenance: "constructed"), M.ShownResult(words: M.resultUnavailable, provenance: nil)),
            (nil, M.ShownResult(words: M.resultUnavailable, provenance: nil)),
        ]
        for (grade, expected) in cases {
            let graded = Self.originals.map { detailsOriginal($0, .final, grade: .some(grade)) }
            let result = try XCTUnwrap(recordedShown(resolve(o, .final, context(o, .final), catalogue: catalogue(.final, graded))))
            XCTAssertEqual(result.content.result, expected)
        }

        // CONSTRUCTED: a real 0 trade is a placed value; a missing one is no point.
        var zero = series(o, .final)
        zero = FieldHistorySeries10868(id: zero.id, name: zero.name, shape: zero.shape, tint: zero.tint,
                                       runs: zero.runs + [FieldHistoryRun10868(id: "constructed-run:zero", points: [
                                           FieldHistoryPoint10868(id: "constructed:zero", x: Self.reportAt, probability: 0, style: .filled)])],
                                       links: [], labelPointID: nil, before: zero.before, recorded: zero.recorded,
                                       absentWords: nil, choose: nil)
        let zeroInput = history(o, .final, series: [zero])
        XCTAssertTrue(G.marks(zero, in: zeroInput).contains { $0.id == "constructed:zero" })
        XCTAssertFalse(G.marks(series(o, .final), in: history(o, .final)).contains { $0.probability == 0 })
    }

    // MARK: - Handback

    func testEachEntryHandsBackItsExactSelectionAndIdOnlyWithACallback() throws {
        let o = Self.kok
        var handed: [M.HistoryIntent] = []
        let onHistory: (M.HistoryIntent) -> Void = { handed.append($0) }
        let ctx = context(o, .final)
        _ = OriginalMarketDetailsView9483(catalogue: catalogue(.final), selection: selection(o), tint: .blue,
                                          recorded: ctx, onHistory: onHistory)
        let live = try XCTUnwrap(recordedShown(resolve(o, .final, ctx, hasCallback: true)))
        _ = resolve(o, .final, ctx, hasCallback: true)
        XCTAssertTrue(handed.isEmpty, "building and rebuilding calls nothing")

        let expected: [(M.HistoryEntry, String)] = [(.preview, Self.preview.id), (.expand, Self.expand.id),
                                                    (.explore, Self.explore.id)]
        for (entry, id) in expected {
            let intent = try XCTUnwrap(M.intent(entry, in: live))
            XCTAssertEqual(intent, M.HistoryIntent(selection: selection(o), entry: entry, actionID: id))
            onHistory(intent)
        }
        XCTAssertEqual(handed.map(\.entry), [.preview, .expand, .explore], "one tap, one exact intent")
        XCTAssertTrue(handed.allSatisfy { $0.selection == selection(o) })

        let still = try XCTUnwrap(recordedShown(resolve(o, .final, ctx, hasCallback: false)))
        XCTAssertNil(still.preview)
        XCTAssertNil(still.expand)
        XCTAssertNil(still.explore)
        XCTAssertTrue(still.showsPlot, "useful static history without a callback")
        XCTAssertEqual(still.content, live.content)
        XCTAssertTrue([M.HistoryEntry.preview, .expand, .explore].allSatisfy { M.intent($0, in: still) == nil })

        let shared = FieldHistoryAction10868(id: Self.preview.id, label: "Explore probability history",
                                             spokenLabel: nil, isAvailable: true)
        let ambiguous = try XCTUnwrap(recordedShown(resolve(o, .final, context(o, .final, explore: shared))))
        XCTAssertNil(ambiguous.preview, "an id shared by two controls is no one's")
        XCTAssertNil(ambiguous.explore)
        XCTAssertEqual(ambiguous.expand, Self.expand)
        let off = FieldHistoryAction10868(id: Self.expand.id, label: Self.expand.label, spokenLabel: nil, isAvailable: false)
        let blankID = FieldHistoryAction10868(id: " ", label: "Explore probability history", spokenLabel: nil, isAvailable: true)
        let blankLabel = FieldHistoryAction10868(id: "constructed-history:preview", label: " ", spokenLabel: nil, isAvailable: true)
        let unusable = try XCTUnwrap(recordedShown(resolve(o, .final, context(o, .final, preview: blankLabel, expand: off,
                                                                      explore: blankID))))
        XCTAssertNil(unusable.preview)
        XCTAssertNil(unusable.expand)
        XCTAssertNil(unusable.explore)
        XCTAssertEqual(handed.count, 3, "resolving never hands anything back")
    }

    func testNilOptInKeepsTheExistingDetailsAndDefaults() throws {
        let o = Self.kok
        for phase in Phase.allCases {
            let content = legacy(o, phase)
            XCTAssertEqual(resolve(o, phase, nil), .legacy(content))
            XCTAssertEqual(resolve(o, phase, nil, hasCallback: false), .legacy(content))
            XCTAssertEqual(content.readings.map(\.label), ["Before race day"])
            XCTAssertEqual(content.marks.count, 1, "the existing rail stays on the legacy path")
        }
        let view = OriginalMarketDetailsView9483(catalogue: catalogue(.final), selection: selection(o), tint: .blue)
        XCTAssertNil(view.recorded)
        XCTAssertNil(view.onHistory)
        let content = legacy(o, .final)
        XCTAssertEqual(M.spoken(content),
                       "Femke Kok (NED). Selected outcome: Wins gold. Before race day 78%, Feb 14, 2:45:25 PM. Original market result: Happened, Settlement time unknown.")
        // The opt-in replaces the earlier reading and draws no rail placement.
        let shown = try XCTUnwrap(recordedShown(resolve(o, .final, context(o, .final))))
        XCTAssertTrue(shown.content.marks.isEmpty)
        XCTAssertEqual(M.spoken(shown),
                       "Femke Kok (NED). Selected outcome: Wins gold. Before race day 78%, Feb 14, 2:45:25 PM. Last recorded trade 99.9%, Feb 15, 10:23:25 AM. Current probability unavailable · recorded history below.")
    }

    // MARK: - Shared history

    func testRealPlotSamplesReachTheSharedHistoryUnchanged() throws {
        XCTAssertEqual(Self.samples.map(\.trades.count), [13, 19])
        for sample in Self.samples {
            let o = try XCTUnwrap(Self.originals.first { $0.seriesID == sample.seriesID })
            for phase in Phase.allCases {
                let ctx = context(o, phase)
                let shown = try XCTUnwrap(recordedShown(resolve(o, phase, ctx)), o.name)
                XCTAssertEqual(shown.history, ctx.history)
                let input = shown.history
                let series = try XCTUnwrap(input.series.first)
                let expected = phase == .before ? Array(sample.trades.prefix(sample.before)) : sample.trades
                XCTAssertEqual(G.marks(series, in: input), expected.map { point($0) }, "\(o.name) \(phase)")
                XCTAssertTrue(G.lines(series, in: input).isEmpty, "dots, never joined")
                // The owner's endpoints are trades of this same series.
                let startIndex = phase == .before ? 0 : sample.before - 1
                XCTAssertEqual(expected[startIndex].id, frame(o, phase).start?.id)
                XCTAssertEqual(expected.last?.id, frame(o, phase).end?.id)
                XCTAssertTrue(G.isDrawable(input))
                XCTAssertTrue(M.isMiniHistory(input))
                XCTAssertEqual(G.blocksAbovePlot(input), [])
                XCTAssertEqual(G.blocksBelowPlot(input), [.selectionWords])
                XCTAssertNil(G.selectionWords(input))
                XCTAssertTrue(G.actions(input).isEmpty, "no child control can nest in the preview")
                XCTAssertEqual(G.chartControlState(input.expand, informative: false, hasCallback: false, in: input), .hidden)
                XCTAssertNil(G.shownInspection(input))
                XCTAssertEqual(G.drawsStyle(.filled, in: input), phase == .final && sample.trades.count > sample.before)
                XCTAssertEqual(G.placedYTicks(input).map(\.lines), [["0%"], [frame(o, phase).top]])
            }
        }
    }

    // MARK: - Compact name, complete disclosure

    /// CONSTRUCTED owner admission of Kok's retained source text (see
    /// `kokRules`): the heading keeps the compact full name while "About this
    /// market" keeps the full market wording, the provider's own rules, the
    /// condition and each side's OWN token — and nothing else moves.
    func testKokCompactNameLeadsWhileItsDisclosureKeepsTheFullWordingAndProviderRules() throws {
        XCTAssertEqual(Self.kokRules.count, 5)
        XCTAssertEqual(Self.kokRules.joined(separator: "\n\n").count, 1_143)
        func full(_ o: O, _ phase: Phase) -> M.Original {
            let packetGrade = frame(o, phase).grade.map { M.Grade(words: $0, provenance: nil) }
            return M.Original(identity: identity(o), title: o.name, outcome: Self.meaning[o.side]!, mode: mode(phase),
                              pregame: legacyReading(o), later: nil, grade: packetGrade,
                              about: M.About(source: "Polymarket", rules: .verified(Self.kokRules),
                                             provenance: [M.Row(label: "Market wording", value: Self.kokPredicate),
                                                          M.Row(label: "Condition", value: Self.kokCondition),
                                                          M.Row(label: "Token", value: Self.kokTokens[o.side]!),
                                                          M.Row(label: "Provider page", value: Self.kokProviderURL)],
                                             historicalQuote: nil),
                              beforeLabel: "Before race day")
        }
        let results = ["Yes": "Happened", "No": "Didn’t happen"]
        for o in [Self.kok, Self.kokNo] {
            let token = try XCTUnwrap(Self.kokTokens[o.side])
            let otherToken = try XCTUnwrap(Self.kokTokens[o.side == "Yes" ? "No" : "Yes"])
            XCTAssertTrue(o.seriesID.hasSuffix(":\(token)"), "the retained token is this side's own series")
            for phase in Phase.allCases {
                let id = "\(o.name) \(o.side) \(phase)"
                let original = full(o, phase)
                let catalogue = self.catalogue(phase, Self.originals.map {
                    $0.marketID == o.marketID ? full($0, phase) : detailsOriginal($0, phase)
                })
                let ctx = context(o, phase)
                let shown = try XCTUnwrap(recordedShown(resolve(o, phase, ctx, catalogue: catalogue)), id)
                let limited = try XCTUnwrap(recordedShown(resolve(o, phase, ctx)), id)

                // The visible and spoken heading is the compact name, never the predicate.
                XCTAssertEqual(shown.content.title, "Femke Kok (NED)", id)
                XCTAssertNotEqual(shown.content.title, Self.kokPredicate, id)
                XCTAssertEqual(M.spoken(shown), M.spoken(limited), id)
                XCTAssertTrue(M.spoken(shown).hasPrefix("Femke Kok (NED). Selected outcome: \(Self.meaning[o.side]!). "), id)
                XCTAssertFalse(M.spoken(shown).contains(Self.kokPredicate), id)

                // About and rules are exactly the existing Details resolver's.
                XCTAssertEqual(shown.content.about, M.about(original), id)
                XCTAssertEqual(shown.content.about, M.content(catalogue: catalogue, selection: selection(o))?.about, id)
                XCTAssertEqual(shown.content.about, [M.Row(label: "Market", value: "Femke Kok (NED)"),
                                                     M.Row(label: "Outcome", value: Self.meaning[o.side]!),
                                                     M.Row(label: "Source", value: "Polymarket"),
                                                     M.Row(label: "Market wording", value: Self.kokPredicate),
                                                     M.Row(label: "Condition", value: Self.kokCondition),
                                                     M.Row(label: "Token", value: token),
                                                     M.Row(label: "Provider page", value: Self.kokProviderURL)], id)
                XCTAssertFalse(shown.content.about.contains(where: { $0.value == otherToken }), "never the other side's token: \(id)")
                XCTAssertEqual(shown.content.rules, .verified(Self.kokRules), id)
                XCTAssertEqual(shown.content.rules, M.rules(original.about.rules), id)
                guard case .verified(let paragraphs) = shown.content.rules else { return XCTFail(id) }
                XCTAssertFalse(paragraphs.contains(Self.rule), "the product note never replaces provider rules: \(id)")

                // Everything else is the same recorded composition.
                XCTAssertEqual(shown.selection, selection(o), id)
                XCTAssertEqual(shown.content.outcome, limited.content.outcome, id)
                XCTAssertEqual(shown.content.readings, limited.content.readings, id)
                XCTAssertEqual(shown.content.result, limited.content.result, id)
                XCTAssertEqual(shown.availability, limited.availability, id)
                XCTAssertEqual(shown.history, ctx.history, id)
                XCTAssertEqual(shown.showsPlot, limited.showsPlot, id)
                XCTAssertEqual(shown.movement, limited.movement, id)
                XCTAssertEqual(shown.finish, limited.finish, id)
                XCTAssertEqual(M.resultSpoken(shown), M.resultSpoken(limited), id)
                let entries: [(M.HistoryEntry, FieldHistoryAction10868)] = [(.preview, Self.preview), (.expand, Self.expand),
                                                                            (.explore, Self.explore)]
                for (entry, action) in entries {
                    XCTAssertEqual(M.intent(entry, in: shown),
                                   M.HistoryIntent(selection: selection(o), entry: entry, actionID: action.id), id)
                }
                switch phase {
                case .before:
                    XCTAssertNil(shown.content.result, id)
                    XCTAssertNil(shown.finish, id)
                case .final:
                    XCTAssertEqual(shown.content.result,
                                   M.ShownResult(words: results[o.side]!, provenance: M.resultTimeUnknown), id)
                    XCTAssertEqual(shown.finish?.words, "Gold · 36.49s", "the physical finish stays separate: \(id)")
                }

                // Nil opt-in keeps the existing Details with the same disclosure.
                let existing = try XCTUnwrap(M.content(catalogue: catalogue, selection: selection(o)), id)
                XCTAssertEqual(resolve(o, phase, nil, catalogue: catalogue), .legacy(existing), id)
                XCTAssertEqual(existing.title, "Femke Kok (NED)", id)
                XCTAssertEqual(existing.rules, .verified(Self.kokRules), id)
            }
        }
    }
